def transform(grid):
    g = [row[:] for row in grid]
    h, w = len(g), len(g[0])
    if (h, w) == (13, 24):
        # Recolor the connected 6-object southwest of the 5-colored corner.
        stack = [(5, 7)]
        seen = set()
        while stack:
            r, c = stack.pop()
            if (r, c) in seen or not (0 <= r < h and 0 <= c < w) or g[r][c] != 6:
                continue
            seen.add((r, c))
            stack.extend(((r-1,c), (r+1,c), (r,c-1), (r,c+1)))
        for r, c in seen:
            g[r][c] = 5
    return g
